 29	///|
 30	async fn command_result(
 31	  program : String,
 32	  args : Array[String],
 33	  stage : String,
 34	  environment? : Map[String, String],
 35	) -> (Int32, String) {
 36	  save_diagnostic(stage, "started")
 37	  let (status, output, _) = {
 38	    errdefer save_diagnostic(stage, "process-error")
 39	    @process.collect_output(
 40	      program,
 41	      args,
 42	      extra_env?=environment,
 43	      inherit_env=environment is None,
 44	    )
 45	  }
 46	  save_diagnostic(
 47	    stage,
 48	    if status == 0 {
 49	      "success"
 50	    } else {
 51	      "exit-error"
 52	    },
 53	    exit_code=status,
 54	  )
 55	  (status, output.text())
 56	}
