 58	///|
 59	async fn command(
 60	  program : String,
 61	  args : Array[String],
 62	  stage : String,
 63	  environment? : Map[String, String],
 64	) -> String {
 65	  let (status, output) = command_result(program, args, stage, environment?)
 66	  guard status == 0 else {
 67	    raise AdapterError(
 68	      "\{stage} failed (exit \{status}); command output withheld",
 69	    )
 70	  }
 71	  output
 72	}
