 74	///|
 75	fn devsy_args(state : Json) -> Array[String] {
 76	  let args = []
 77	  for name in ["home", "context"] {
 78	    if field(state, name) is Some(Json::String(value)) {
 79	      args.push("--" + name)
 80	      args.push(value)
 81	    }
 82	  }
 83	  args
 84	}
