 86	///|
 87	async fn devsy_result(
 88	  state : Json,
 89	  args : Array[String],
 90	  stage : String,
 91	) -> (Int32, String) {
 92	  let environment = @env.get_env_vars()
 93	  for name in location_variables {
 94	    match field(field(state, "devsyEnv").unwrap(), name) {
 95	      Some(Json::String(value)) => environment.set(name, value)
 96	      _ => environment.remove(name)
 97	    }
 98	  }
 99	  let invocation = saved_command(state)
100	  command_result(
101	    invocation[0],
102	    invocation[1:].to_owned() + devsy_args(state) + args,
103	    stage,
104	    environment~,
105	  )
106	}
