183	///|
184	fn up_result(output : String) -> Json raise {
185	  let results = []
186	  for line in output.split("\n") {
187	    if line.trim() != "" {
188	      let parsed = @json.parse(line.to_owned())
189	      if field(parsed, "kind") == Some(Json::string("result")) {
190	        results.push(parsed)
191	      }
192	    }
193	  }
194	  guard results.length() == 1 &&
195	    field(results[0], "outcome") == Some(Json::string("success")) else {
196	    raise AdapterError(
197	      "Devsy did not return exactly one successful workspace result",
198	    )
199	  }
200	  results[0]
201	}
