204	async fn read_document(path : String) -> Json {
205	  let data = @fs.read_file(path)
206	  let docs = @yaml.Yaml::load_from_string(data.text())
207	  guard docs.length() == 1 else {
208	    raise AdapterError("orca.yaml must contain exactly one YAML document")
209	  }
210	  docs[0].to_json()
211	}
