641	///|
642	async fn execute_inner(mode : String) -> Unit {
643	  notify(mode)
644	  let (state, previous) = if mode == "create" {
645	    (create_state(), Json::null())
646	  } else {
647	    lifecycle_state(mode)
648	  }
649	  match mode {
650	    "create" => {
651	      errdefer discard_created_workspace(state)
652	      codex_addon(state)
653	      emit_connection(state, true)
654	    }
655	    "resume" => {
656	      ignore(
657	        devsy(
658	          state,
659	          [
660	            "--result-format",
661	            "json",
662	            "workspace",
663	            "up",
664	            required(state, "workspaceId"),
665	            "--ide-launch",
666	            "skip",
667	          ],
668	          "workspace-resume",
669	        ),
670	      )
671	      codex_addon(state)
672	      emit_connection(state, false)
673	    }
674	    "reconnect" => emit_connection(state, false, existing=previous)
675	    "suspend" => {
676	      ignore(
677	        devsy(
678	          state,
679	          ["workspace", "stop", required(state, "workspaceId")],
680	          "workspace-stop",
681	        ),
682	      )
683	      close_tunnel(state)
684	    }
685	    "destroy" => {
686	      ignore(
687	        devsy(
688	          state,
689	          [
690	            "workspace",
691	            "delete",
692	            required(state, "workspaceId"),
693	            "--ignore-not-found",
694	          ],
695	          "workspace-delete",
696	        ),
697	      )
698	      close_tunnel(state)
699	    }
700	    _ => raise AdapterError("Unknown command")
701	  }
702	  save_diagnostic(mode, "success")
703	}
