767	fn valid_commit(value : String) -> Bool {
768	  (value.length() == 40 || value.length() == 64) &&
769	  value
770	  .to_array()
771	  .iter()
772	  .all(c => (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f'))
