827	fn valid_workspace_id(id : String) -> Bool {
828	  id.length() > 0 &&
829	  id.length() <= 48 &&
830	  ((id[0] >= 'a' && id[0] <= 'z') || (id[0] >= '0' && id[0] <= '9')) &&
831	  id
832	  .to_array()
833	  .iter()
834	  .all(c => (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-')
835	}
