837	///|
838	fn valid_context(value : String) -> Bool {
839	  value != "" &&
840	  value
841	  .to_array()
842	  .iter()
843	  .all(c => {
844	    (c >= 'a' && c <= 'z') ||
845	    (c >= 'A' && c <= 'Z') ||
846	    (c >= '0' && c <= '9') ||
847	    c == '_' ||
848	    c == '-'
849	  })
850	}
