852	///|
853	fn valid_user(user : String) -> Bool {
854	  let name = if user.has_suffix("$") {
855	    user[:user.length() - 1].to_owned()
856	  } else {
857	    user
858	  }
859	  name != "" &&
860	  user.length() <= 64 &&
861	  (
862	    (name[0] >= 'a' && name[0] <= 'z') ||
863	    (name[0] >= 'A' && name[0] <= 'Z') ||
864	    name[0] == '_'
865	  ) &&
866	  name
867	  .to_array()
868	  .iter()
869	  .all(c => {
870	    (c >= 'a' && c <= 'z') ||
871	    (c >= 'A' && c <= 'Z') ||
872	    (c >= '0' && c <= '9') ||
873	    c == '_' ||
874	    c == '-'
875	  })
876	}
