878	///|
879	fn shallow_branch(build_ref : String) -> String? {
880	  if build_ref == "HEAD" ||
881	    valid_commit(build_ref) ||
882	    (build_ref.has_prefix("refs/") && !build_ref.has_prefix("refs/heads/")) {
883	    return None
884	  }
885	  let branch = if build_ref.has_prefix("refs/heads/") {
886	    build_ref[11:].to_owned()
887	  } else {
888	    build_ref
889	  }
890	  if branch != "" &&
891	    branch
892	    .to_array()
893	    .iter()
894	    .all(c => {
895	      (c >= 'a' && c <= 'z') ||
896	      (c >= 'A' && c <= 'Z') ||
897	      (c >= '0' && c <= '9') ||
898	      c == '/' ||
899	      c == '.' ||
900	      c == '_' ||
901	      c == '-'
902	    }) {
903	    Some(branch)
904	  } else {
905	    None
906	  }
907	}
