909	///|
910	fn missing_shallow_commit(output : String, commit : String) -> Bool {
911	  output
912	  .split("\n")
913	  .iter()
914	  .any(line => {
915	    if line.trim() == "" {
916	      return false
917	    }
918	    let event = @json.parse(line.to_owned())
919	    let missing = match
920	      field(field(event, "error").unwrap_or(Json::null()), "message") {
921	      Some(Json::String(message)) =>
922	        message.contains("Could not parse object '" + commit + "'")
923	      _ => false
924	    }
925	    field(event, "kind") == Some(Json::string("status")) &&
926	    field(event, "phase") == Some(Json::string("cloning_repository")) &&
927	    field(event, "state") == Some(Json::string("failed")) &&
928	    missing
929	  }) catch {
930	    _ => false
931	  }
932	}

