124	///|
125	fn proxy(state : Json) -> String raise {
126	  let args = ["env"]
127	  for name in location_variables {
128	    args.push("-u")
129	    args.push(name)
130	  }
131	  for name in location_variables {
132	    if field(field(state, "devsyEnv").unwrap(), name)
133	      is Some(Json::String(value)) {
134	      args.push(name + "=" + value)
135	    }
136	  }
137	  // bash accepts exec --, while dash treats -- as an executable. Probe the
138	  // builtin in a subshell to preserve leading-dash command names on both.
139	  (args +
140	  [
141	    "/bin/sh", "-c", "if (exec --) 2>/dev/null; then exec -- \"$@\"; else exec \"$@\"; fi",
142	    "sh",
143	  ] +
144	  saved_command(state) +
145	  devsy_args(state) +
146	  [
147	    "workspace",
148	    "ssh",
149	    required(state, "workspaceId"),
150	    "--stdio",
151	    "--user",
152	    required(state, "user"),
153	  ])
154	  .map(quote)
155	  .join(" ")
156	  .replace_all(old="%", new="%%")
157	}
