223	    let home = environment("HOME")
224	    let dir = home + "/.local/state/orca-env-devsy"
225	    @fs.mkdir(dir, permission=0o700, recursive=true, allow_exist=true)
226	    @fs.chmod(dir, 0o700)
227	    let path = dir + "/events.jsonl"
228	    if @fs.exists(path) &&
229	      @fs.kind(path, follow_symlink=false) != @fs.FileKind::Regular {
230	      return
231	    }
232	    if @fs.exists(path) && @fs.file_size(path) > 262144L {
233	      @fs.remove(path)
234	    }
235	    let event : Json = {
236	      "stage": stage,
237	      "status": status,
238	      "time": @env.now().to_string(),
239	      "runId": recording_run_id,
240	    }
241	    if exit_code is Some(code) {
242	      set_field(event, "exitCode", Json::number(code.to_double()))
243	    }
244	    @fs.write_file(
245	      path,
246	      event.stringify() + "\n",
247	      permission=0o600,
248	      append=true,
249	      create_mode=@fs.OpenOrCreate,
250	    )
251	  } catch {
252	    _ => ()
253	  }
254	}
