265	///|
266	async fn create_state() -> Json {
267	  let document = read_document(environment("ORCA_REPO_PATH") + "/orca.yaml")
268	  let id = environment("ORCA_RECIPE_ID")
269	  let config = resolve_settings(document, id, name => @env.get_env_var(name))
270	  let recipes = match field(document, "environmentRecipes") {
271	    Some(Json::Array(items)) => items
272	    _ => []
273	  }
274	  let recipe = recipes.filter(item => {
275	      field(item, "id") == Some(Json::string(id))
276	    })[0]
277	  let mode = string_field(recipe, "checkoutMode", "recipe").unwrap_or(
278	    "orca-worktree",
279	  )
280	  guard mode == "orca-worktree" || mode == "provisioned-root" else {
281	    raise AdapterError("Invalid checkoutMode")
282	  }
283	  guard !(mode == "provisioned-root" && config.connection == Server) else {
284	    raise AdapterError("provisioned-root requires SSH")
285	  }
286	  guard valid_workspace_id(environment("ORCA_VM_INSTANCE_ID")) else {
287	    raise AdapterError("Invalid workspace identity")
288	  }
289	  if config.home is Some(home) {
290	    guard home.has_prefix("/") else {
291	      raise AdapterError("devsy.home must be absolute")
292	    }
293	  }
294	  if config.context is Some(context) {
295	    guard valid_context(context) else {
296	      raise AdapterError("Invalid devsy.context")
297	    }
298	  }
299	  if mode == "provisioned-root" {
300	    guard valid_commit(environment("ORCA_REPO_REF_HEAD")) else {
301	      raise AdapterError("Invalid provisioned-root commit")
302	    }
303	    let branch = environment("ORCA_REPO_BRANCH")
304	    guard !branch.has_prefix("-") else {
305	      raise AdapterError("Invalid provisioned-root branch")
306	    }
307	    ignore(
308	      command(
309	        "git",
310	        ["check-ref-format", "refs/heads/" + branch],
311	        "validate-branch",
312	      ),
313	    )
314	  }
315	  let state : Json = {
316	    "adapterVersion": 1,
317	    "workspaceId": environment("ORCA_VM_INSTANCE_ID"),
318	    "connection": if config.connection == Server {
319	      "orca-server"
320	    } else {
321	      "ssh"
322	    },
323	    "checkoutMode": mode,
324	    "codexAuth": config.codex_auth,
325	  }
326	  let locations = Json::empty_object()
327	  for name in location_variables {
328	    set_field(
329	      locations,
330	      name,
331	      match @env.get_env_var(name) {
332	        Some(value) => Json::string(value)
333	        None => Json::null()
334	      },
335	    )
336	  }
337	  set_field(state, "command", Json::array(config.command.map(Json::string)))
338	  set_field(state, "devsyEnv", locations)
339	  if config.home is Some(value) {
340	    set_field(state, "home", Json::string(value))
341	  }
342	  if config.context is Some(value) {
343	    set_field(state, "context", Json::string(value))
344	  }
345	  let contexts = @json.parse(
346	    devsy(
347	      state,
348	      ["--result-format", "json", "context", "list"],
349	      "resolve-context",
350	    ),
351	  )
352	  guard contexts is Json::Array(context_items) else {
353	    raise AdapterError("Invalid Devsy context list")
354	  }
355	  let defaults = context_items.filter(item => {
356	    field(item, "default") == Some(Json::boolean(true))
357	  })
358	  guard defaults.length() == 1 else {
359	    raise AdapterError("No unique effective Devsy context")
360	  }
361	  set_field(state, "context", Json::string(required(defaults[0], "name")))
362	  let repository = match @env.get_env_var("ORCA_REPO_URL") {
363	    Some(url) if url != "" => url
364	    _ =>
365	      command(
366	        "git",
367	        ["-C", environment("ORCA_REPO_PATH"), "remote", "get-url", "origin"],
368	        "repository-remote",
369	      )
370	      .trim()
371	      .to_owned()
372	  }
373	  guard !repository.contains("?") && !repository.contains("#") else {
374	    raise AdapterError(
375	      "Repository URL must not contain credentials or query parameters",
376	    )
377	  }
378	  if repository.has_prefix("ssh://") {
379	    let authority = repository.split("/").to_array()[2]
380	    if authority.split_once("@") is Some((userinfo, _)) {
381	      guard !userinfo.contains(":") else {
382	        raise AdapterError("Repository URL must not contain credentials")
383	      }
384	    }
385	  }
386	  if repository.has_prefix("https://") || repository.has_prefix("http://") {
387	    guard !repository.split("/").to_array()[2].contains("@") else {
388	      raise AdapterError("Repository URL must not contain credentials")
389	    }
390	  }
391	  let build_ref = config.build_ref.unwrap_or("HEAD")
392	  let hash = if valid_commit(build_ref) {
393	    build_ref
394	  } else {
395	    let resolved = command(
396	        "git",
397	        ["ls-remote", "--", repository, build_ref, build_ref + "^{}"],
398	        "resolve-build-ref",
399	      )
400	      .trim()
401	      .to_owned()
402	    let lines = resolved.split("\n").to_array()
403	    let peeled = lines.filter(line => line.has_suffix("^{}"))
404	    let selected = if peeled.length() == 1 && lines.length() <= 2 {
405	      peeled
406	    } else {
407	      lines
408	    }
409	    guard selected.length() == 1 &&
410	      selected[0].split_once("\t") is Some((commit, _)) else {
411	      raise AdapterError("buildRef must resolve to one remote ref or commit")
412	    }
413	    commit.to_owned()
414	  }
415	  guard valid_commit(hash) else {
416	    raise AdapterError("Invalid remote build commit")
417	  }
418	  set_field(state, "buildRef", Json::string(build_ref))
419	  set_field(state, "buildCommit", Json::string(hash))
420	  notify("workspace-create")
421	  guard workspace(state) == None else {
422	    raise AdapterError("Workspace ID already exists")
423	  }
424	  for argument in config.up_args {
425	    guard ![
426	        "--id", "--uid", "--home", "--context", "--result-format", "--ide-launch",
427	        "--",
428	      ]
429	      .iter()
430	      .any(flag => argument == flag || argument.has_prefix(flag + "=")) else {
431	      raise AdapterError("upArgs cannot override adapter-owned options")
432	    }
433	  }
434	  let reservation = @fs.tmpdir(prefix="oe-create-")
435	  let uid = reservation.split("/").to_array().last().unwrap().to_owned() +
436	    "-" +
437	    @env.now().to_string()
438	  @fs.rmdir(reservation)
439	  set_field(state, "workspaceUid", Json::string(uid))
440	  errdefer discard_created_workspace(state)
441	  let create_args = fn(source : String, strategy : String) raise {
442	    [
443	      "--result-format",
444	      "json",
445	      "--uid",
446	      required(state, "workspaceUid"),
447	      "workspace",
448	      "up",
449	      source,
450	      "--id",
451	      required(state, "workspaceId"),
452	      "--ide-launch",
453	      "skip",
454	      "--git-clone-strategy=" + strategy,
455	    ] +
456	    config.up_args
457	  }
458	  let args = create_args(repository + "@sha256:" + hash, "")
459	  let shallow = if config.up_args
460	    .iter()
461	    .any(arg => {
462	      arg == "--git-clone-strategy" || arg.has_prefix("--git-clone-strategy=")
463	    }) {
464	    None
465	  } else {
466	    shallow_branch(build_ref)
467	  }
468	  let output = if shallow is Some(branch) {
469	    ignore(
470	      command(
471	        "git",
472	        ["check-ref-format", "refs/heads/" + branch],
473	        "validate-build-branch",
474	      ),
475	    )
476	    let shallow_args = create_args(
477	      repository + "@sha256:" + hash + "@" + branch,
478	      "shallow",
479	    )
480	    let (status, output) = devsy_result(state, shallow_args, "workspace-create")
481	    if status != 0 && missing_shallow_commit(output, hash) {
482	      save_diagnostic("clone-fallback", "started")
483	      devsy(state, args, "workspace-create-full")
484	    } else {
485	      guard status == 0 else {
486	        raise AdapterError(
487	          "workspace-create failed (exit \{status}); command output withheld",
488	        )
489	      }
490	      output
491	    }
492	  } else {
493	    devsy(state, args, "workspace-create")
494	  }
495	  let created = workspace(state).unwrap()
496	  guard required(created, "uid") == uid else {
497	    raise AdapterError("Created workspace identity does not match request")
498	  }
499	  let result = up_result(output)
500	  set_field(state, "user", Json::string(required(result, "remoteUser")))
501	  validate_state(state)
502	  let root_script = match field(result, "remoteWorkspaceFolder") {
503	    Some(Json::String(folder)) => {
504	      guard folder == "" ||
505	        (
506	          folder.has_prefix("/") &&
507	          !folder.contains("\n") &&
508	          !folder.contains("\r")
509	        ) else {
510	        raise AdapterError("Invalid remote workspace folder")
511	      }
512	      if folder == "" {
513	        ""
514	      } else {
515	        "cd " + quote(folder) + " && "
516	      }
517	    }
518	    None => ""
519	    _ => raise AdapterError("Invalid remote workspace folder")
520	  }
521	  let root = remote(
522	      state,
523	      root_script +
524	      "test \"$(pwd -P)\" = \"$(git rev-parse --show-toplevel)\" && pwd -P",
525	      "resolve-root",
526	    )
527	    .trim()
528	    .to_owned()
529	  guard root.has_prefix("/") && !root.contains("\n") && !root.contains("\r") else {
530	    raise AdapterError("Invalid remote project root")
531	  }
532	  let actual_commit = remote(
533	      state,
534	      "git -C " + quote(root) + " rev-parse HEAD",
535	      "verify-build-commit",
536	    )
537	    .trim()
538	    .to_owned()
539	  guard actual_commit == hash else {
540	    raise AdapterError(
541	      "Remote build checkout does not match resolved build commit",
542	    )
543	  }
544	  set_field(state, "buildCommit", Json::string(actual_commit))
545	  set_field(state, "projectRoot", Json::string(root))
546	  if mode == "provisioned-root" {
547	    let head = environment("ORCA_REPO_REF_HEAD")
548	    let branch = environment("ORCA_REPO_BRANCH")
549	    guard valid_commit(head) && !branch.has_prefix("-") else {
550	      raise AdapterError("Invalid provisioned-root checkout identity")
551	    }
552	    let script = "cd " +
553	      quote(root) +
554	      " && git fetch origin " +
555	      quote(head) +
556	      " && git checkout -B " +
557	      quote(branch) +
558	      " " +
559	      quote(head)
560	    ignore(remote(state, script, "checkout-workspace"))
561	  }
562	  state
563	}
