565	///|
566	async fn lifecycle_state(mode : String) -> (Json, Json) {
567	  let input = @stdio.stdin.read_all()
568	  let payload = @json.parse(input.text())
569	  guard field(payload, "schemaVersion") == Some(Json::number(1)) else {
570	    raise AdapterError("Invalid lifecycle payload schema")
571	  }
572	  let result = match field(payload, "recipeResult") {
573	    Some(value) => value
574	    None => raise AdapterError("Missing recipeResult")
575	  }
576	  let state = match field(result, "userData") {
577	    Some(value) => value
578	    None => raise AdapterError("Missing saved adapter state")
579	  }
580	  guard field(state, "adapterVersion") == Some(Json::number(1)) else {
581	    raise AdapterError("Unsupported adapter state")
582	  }
583	  validate_state(state)
584	  match workspace(state) {
585	    Some(current) if field(current, "uid") == field(state, "workspaceUid") => ()
586	    None if mode == "destroy" => ()
587	    _ => raise AdapterError("Workspace missing or replaced")
588	  }
589	  (state, result)
590	}
