592	///|
593	async fn emit_connection(
594	  state : Json,
595	  install : Bool,
596	  existing? : Json,
597	) -> Unit {
598	  let connection = if required(state, "connection") == "ssh" {
599	    let target : Json = {
600	      "label": "Devsy",
601	      "host": "devsy-workspace",
602	      "port": 22,
603	      "username": required(state, "user"),
604	      "proxyCommand": proxy(state),
605	    }
606	    let output : Json = {
607	      "type": "ssh",
608	      "projectRoot": required(state, "projectRoot"),
609	      "target": target,
610	    }
611	    output
612	  } else if existing is Some(result) {
613	    let port = match field(state, "localPort") {
614	      Some(Json::Number(port, ..)) => port.to_int()
615	      _ => raise AdapterError("Missing saved tunnel port")
616	    }
617	    ensure_tunnel(state, port)
618	    match field(result, "connection") {
619	      Some(value) => value
620	      None => raise AdapterError("Missing saved connection")
621	    }
622	  } else {
623	    server_connection(state, install)
624	  }
625	  let version = if required(state, "checkoutMode") == "provisioned-root" {
626	    2
627	  } else {
628	    1
629	  }
630	  let output : Json = {
631	    "schemaVersion": version,
632	    "connection": connection,
633	    "userData": state,
634	  }
635	  if version == 2 {
636	    set_field(output, "checkoutMode", Json::string("provisioned-root"))
637	  }
638	  @stdio.stdout.write(output.stringify() + "\n")
639	}
