744	///|
745	async fn workspace(state : Json) -> Json? {
746	  let listing = @json.parse(
747	    devsy(
748	      state,
749	      ["--result-format", "json", "workspace", "list", "--skip-pro"],
750	      "workspace-list",
751	    ),
752	  )
753	  guard listing is Json::Array(items) else {
754	    raise AdapterError("Invalid workspace list")
755	  }
756	  let matches = items.filter(item => {
757	    field(item, "id") == field(state, "workspaceId")
758	  })
759	  match matches {
760	    [] => None
761	    [single] => Some(single)
762	    _ => raise AdapterError("Duplicate workspace ID")
763	  }
764	}
