789	///|
790	async fn discard_created_workspace(state : Json) -> Unit {
791	  @async.protect_from_cancel(async fn() {
792	    try {
793	      @async.with_timeout(45000, async fn() {
794	        guard workspace(state) is Some(current) &&
795	          field(current, "uid") == field(state, "workspaceUid") else {
796	          return
797	        }
798	        if field(state, "user") is Some(_) {
799	          close_tunnel(state)
800	        }
801	        ignore(
802	          devsy(
803	            state,
804	            [
805	              "workspace",
806	              "delete",
807	              required(state, "workspaceId"),
808	              "--ignore-not-found",
809	            ],
810	            "create-cleanup",
811	          ),
812	        )
813	      })
814	      save_diagnostic("create-cleanup", "success")
815	    } catch {
816	      _ => {
817	        @stdio.stderr.write(
818	          "orca-env-devsy: warning: create cleanup failed; inspect the workspace with Devsy\n",
819	        )
820	        save_diagnostic("create-cleanup", "warning")
821	      }
822	    }
823	  })
824	}
