826	///|
827	fn valid_workspace_id(id : String) -> Bool {
828	  id.length() > 0 &&
829	  id.length() <= 48 &&
830	  ((id[0] >= 'a' && id[0] <= 'z') || (id[0] >= '0' && id[0] <= '9')) &&
831	  id
832	  .to_array()
833	  .iter()
834	  .all(c => (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-')
835	}
836	
837	///|
838	fn valid_context(value : String) -> Bool {
839	  value != "" &&
840	  value
841	  .to_array()
842	  .iter()
843	  .all(c => {
844	    (c >= 'a' && c <= 'z') ||
845	    (c >= 'A' && c <= 'Z') ||
846	    (c >= '0' && c <= '9') ||
847	    c == '_' ||
848	    c == '-'
849	  })
850	}
851	
852	///|
853	fn valid_user(user : String) -> Bool {
854	  let name = if user.has_suffix("$") {
855	    user[:user.length() - 1].to_owned()
856	  } else {
857	    user
858	  }
859	  name != "" &&
860	  user.length() <= 64 &&
861	  (
862	    (name[0] >= 'a' && name[0] <= 'z') ||
863	    (name[0] >= 'A' && name[0] <= 'Z') ||
864	    name[0] == '_'
865	  ) &&
866	  name
867	  .to_array()
868	  .iter()
869	  .all(c => {
870	    (c >= 'a' && c <= 'z') ||
871	    (c >= 'A' && c <= 'Z') ||
872	    (c >= '0' && c <= '9') ||
873	    c == '_' ||
874	    c == '-'
875	  })
876	}
877	
878	///|
879	fn shallow_branch(build_ref : String) -> String? {
880	  if build_ref == "HEAD" ||
881	    valid_commit(build_ref) ||
882	    (build_ref.has_prefix("refs/") && !build_ref.has_prefix("refs/heads/")) {
883	    return None
884	  }
885	  let branch = if build_ref.has_prefix("refs/heads/") {
886	    build_ref[11:].to_owned()
887	  } else {
888	    build_ref
889	  }
890	  if branch != "" &&
891	    branch
892	    .to_array()
893	    .iter()
894	    .all(c => {
895	      (c >= 'a' && c <= 'z') ||
896	      (c >= 'A' && c <= 'Z') ||
