   592	///|
   593	async fn emit_connection(
   594	  state : Json,
   595	  install : Bool,
   596	  existing? : Json,
   597	) -> Unit {
   598	  let connection = if required(state, "connection") == "ssh" {
   599	    let target : Json = {
   600	      "label": "Devsy",
   601	      "host": "devsy-workspace",
   602	      "port": 22,
   603	      "username": required(state, "user"),
   604	      "proxyCommand": proxy(state),
