    90	///|
    91	async fn read_codex_auth(home : String) -> CodexAuth {
    92	  guard @fs.file_size(home + "/auth.json") <= 65536L else {
    93	    raise AdapterError("Invalid Codex auth size")
    94	  }
    95	  let source = @fs.read_file(home + "/auth.json")
    96	  guard source.binary().length() <= 65536 else {
    97	    raise AdapterError("Invalid Codex auth size")
    98	  }
    99	  let auth = @json.parse(source.text())
   100	  guard (
   101	      field(auth, "OPENAI_API_KEY") == None ||
   102	      field(auth, "OPENAI_API_KEY") == Some(Json::null())
   103	    ) &&
   104	    (
   105	      field(auth, "auth_mode") == None ||
   106	      field(auth, "auth_mode") == Some(Json::string("chatgpt"))
   107	    ) else {
   108	    raise AdapterError("Unsupported Codex auth mode")
   109	  }
   110	  let tokens = field(auth, "tokens").unwrap()
   111	  let access = required(tokens, "access_token")
   112	  let segments = access.split(".").to_array()
   113	  guard segments.length() == 3 else {
   114	    raise AdapterError("Invalid access token")
   115	  }
   116	  let encoded = segments[1]
   117	    .to_owned()
   118	    .replace_all(old="-", new="+")
   119	    .replace_all(old="_", new="/")
   120	  let padding = (4 - encoded.length() % 4) % 4
   121	  let claims = @json.parse(
   122	    @utf8.decode(@base64.decode(encoded + "=".repeat(padding))),
   123	  )
   124	  guard field(claims, "exp") is Some(Json::Number(expiry, ..)) else {
   125	    raise AdapterError("Invalid access token expiry")
   126	  }
   127	  { access, account: required(tokens, "account_id"), expiry, }
   128	}
