   130	///|
   131	async fn codex_rpc_response(
   132	  reader : @process.ReadFromProcess,
   133	  id : Int32,
   134	) -> Unit {
   135	  let bytes : Array[Byte] = []
   136	  let mut total = 0
   137	  while true {
   138	    let byte = reader.read_exactly(1)[0]
   139	    total += 1
   140	    guard total <= 1048576 else {
   141	      raise AdapterError("Codex refresh output limit")
   142	    }
   143	    if byte == b'\n' {
   144	      let response = @json.parse(@utf8.decode(Bytes::from_array(bytes)))
   145	      bytes.clear()
   146	      if field(response, "id") == Some(Json::number(id.to_double())) {
   147	        guard field(response, "error") == None &&
   148	          field(response, "result") != None else {
   149	          raise AdapterError("Codex refresh RPC failed")
   150	        }
   151	        return
   152	      }
   153	    } else {
   154	      bytes.push(byte)
   155	    }
   156	  }
   157	}
