   160	async fn refresh_codex(home : String) -> Unit {
   161	  let (reader, output) = @process.read_from_process()
   162	  defer reader.close()
   163	  let (input, writer) = @process.write_to_process()
   164	  defer writer.close()
   165	  let sink = @process.redirect_to_file("/dev/null", shared=true)
   166	  defer sink.close()
   167	  @async.with_task_group(async fn(group) {
   168	    ignore(
   169	      @process.spawn(
   170	        group,
   171	        "codex",
   172	        ["app-server", "--stdio"],
   173	        extra_env={ "CODEX_HOME": home },
   174	        stdin=input,
   175	        stdout=output,
   176	        stderr=sink,
   177	        no_wait=true,
   178	      ),
   179	    )
   180	    let initialize : Json = {
   181	      "id": 1,
   182	      "method": "initialize",
   183	      "params": {
   184	        "clientInfo": { "name": "orca-env-devsy", "version": version },
   185	      },
   186	    }
   187	    writer.write(initialize.stringify() + "\n")
   188	    codex_rpc_response(reader, 1)
   189	    writer.write("{\"method\":\"initialized\"}\n")
   190	    writer.write(
   191	      "{\"id\":2,\"method\":\"account/read\",\"params\":{\"refreshToken\":true}}\n",
   192	    )
