   198	async fn codex_credentials(home : String) -> CodexAuth {
   199	  let initial = read_codex_auth(home)
   200	  if initial.expiry - @env.now().to_double() / 1000 >= 604800 {
   201	    return initial
   202	  }
   203	  let lock = @fs.open(
   204	    home + "/.orca-env-devsy-refresh.lock",
   205	    mode=ReadWrite,
   206	    create_mode=OpenOrCreate,
   207	    permission=0o600,
   208	  )
   209	  defer lock.close()
   210	  while !lock.try_lock(Exclusive) {
   211	    @async.sleep(100)
   212	  }
   213	  let before = read_codex_auth(home)
   214	  if before.expiry - @env.now().to_double() / 1000 >= 604800 {
   215	    return before
   216	  }
   217	  try {
   218	    refresh_codex(home)
   219	    let after = read_codex_auth(home)
   220	    guard after.access != before.access && after.expiry > before.expiry else {
   221	      raise AdapterError("Codex refresh not persisted")
   222	    }
   223	    save_diagnostic("codex-refresh", "success")
   224	  } catch {
   225	    _ => {
   226	      @stdio.stderr.write(
   227	        "orca-env-devsy: warning: Codex refresh failed; checking remaining token lifetime\n",
   228	      )
   229	      save_diagnostic("codex-refresh", "warning")
   230	    }
   231	  }
   232	  let current = read_codex_auth(home)
   233	  guard current.expiry > @env.now().to_double() / 1000 else {
   234	    raise AdapterError("Expired access token")
   235	  }
   236	  if current.expiry - @env.now().to_double() / 1000 < 604800 {
   237	    @stdio.stderr.write(
   238	      "orca-env-devsy: warning: Codex token has less than seven days remaining\n",
   239	    )
   240	  }
   241	  current
   242	}
