func GetDefaultExtraEnv(strictHostKeyChecking bool) []string {
	newExtraEnv := []string{"GIT_TERMINAL_PROMPT=0"}
	sshArgs := "GIT_SSH_COMMAND=ssh -oBatchMode=yes -oStrictHostKeyChecking="
	if strictHostKeyChecking {
