async function refresh(
  cli: string,
  home: string,
  signal: AbortSignal,
): Promise<void> {
  await process(
    {
      command: cli,
      args: ["app-server", "--stdio"],
      env: { CODEX_HOME: home },
    },
    signal,
    async (writer, reader) => {
      let buffer = "";
      let size = 0;
      const send = async (value: unknown) =>
        await writer.write(encoder.encode(JSON.stringify(value) + "\n"));
      const response = async (id: number) => {
        while (true) {
          const newline = buffer.indexOf("\n");
          if (newline >= 0) {
            const line = buffer.slice(0, newline);
            buffer = buffer.slice(newline + 1);
            const message = object(JSON.parse(line));
            if (message.id === id) {
              if (
                message.error !== undefined || message.result === undefined
              ) throw new Error("refresh-rpc");
              return;
            }
          } else {
            const chunk = await reader.read();
            if (chunk.done) throw new Error("refresh-eof");
            size += chunk.value.length;
            if (size > 1048576) throw new Error("refresh-output-limit");
            buffer += decoder.decode(chunk.value, { stream: true });
          }
        }
      };
      await send({
        id: 1,
        method: "initialize",
        params: { clientInfo: { name: "glaze-devsy", version: "1" } },
      });
      await response(1);
      await send({ method: "initialized" });
      await send({
        id: 2,
        method: "account/read",
        params: { refreshToken: true },
      });
      await response(2);
    },
  );
}

/** OS advisory lock only serializes this task; other Codex processes remain independent. */
async function refreshFile(
  cli: string,
  home: string,
  signal: AbortSignal,
  report: (event: Event) => void,
): Promise<Auth | undefined> {
  const path = join(home, ".glaze-devsy-refresh.lock");
  const file = await Deno.open(path, {
    read: true,
    write: true,
    create: true,
    mode: 0o600,
  });
  try {
    const deadline = Date.now() + 45_000;
    while (!await file.tryLock(true)) {
      signal.throwIfAborted();
      if (Date.now() >= deadline) throw new Error("refresh-lock-timeout");
      await new Promise((resolve) => setTimeout(resolve, 100));
    }
    signal.throwIfAborted();
    const before = await auth(home);
    if (!before || before.expires - Date.now() / 1000 >= week) return before;
    try {
      await refresh(cli, home, signal);
      const after = await auth(home);
      if (
        !after || after.access === before.access ||
        after.expires <= before.expires
      ) throw new Error("refresh-not-persisted");
      report({
        stage: "refresh",
        status: "success",
        reason: "refreshed",
        remainingSeconds: Math.floor(after.expires - Date.now() / 1000),
"}

